    public static IEnumerable<object[]> CaseNames()
    {
        foreach (string name in Cases.Keys)
        {
            yield return [name];
        }
    }

    private static StyleContext ContextOf(string name, Node r) => name switch
    {
        "st-hover" => StyleContext.Default with { Hover = r },
        "st-active" => StyleContext.Default with { Active = r },
        "st-focus" => StyleContext.Default with { Focus = r, FocusSource = FocusSource.PointingDevice },
        "st-fv" => StyleContext.Default with { Focus = r, FocusSource = FocusSource.Keyboard },
        _ => StyleContext.Default,
    };

    [Theory]
    [MemberData(nameof(CaseNames))]
    public void Parts_compute_as_Chrome_reports(string name)
    {
        (string html, string expected) = Cases[name];
        Document doc = Document.Parse(html);
        Node r = doc.GetElementById("r");
        DocumentStyles styles = DocumentStyles.Create(doc, ContextOf(name, r));
        ComputedStyle thumb = styles.GetPseudoStyle(r, PseudoElementKind.SliderThumb)!;
        ComputedStyle track = styles.GetPseudoStyle(r, PseudoElementKind.SliderTrack)!;
        var wrong = new List<string>();
        int n = 0;
        foreach (string item in expected.Split(';', StringSplitOptions.RemoveEmptyEntries))
        {
            int dot = item.IndexOf('.', StringComparison.Ordinal);
            int eq = item.IndexOf('=', StringComparison.Ordinal);
            string property = item.Substring(dot + 1, eq - dot - 1);
            string want = item.Substring(eq + 1);
            string got = (item.StartsWith("thumb.", StringComparison.Ordinal) ? thumb : track).GetPropertyValue(property);
            n++;
            if (got != want)
            {
                wrong.Add($"{item.Substring(0, eq)}: expected {want}, got {got}");
            }
        }

        Assert.True(n > 0);
        Assert.True(wrong.Count == 0, string.Join("; ", wrong));
    }

    [Fact]
    public void A_text_input_has_no_parts_though_Chrome_gives_it_a_plain_style()
    {
        Document doc = Document.Parse("<style>input::-webkit-slider-thumb{color:red}</style><input id=r type=text>");
        DocumentStyles styles = DocumentStyles.Create(doc);
        Assert.Null(styles.GetPseudoStyle(doc.GetElementById("r"), PseudoElementKind.SliderThumb));
        Assert.Null(styles.GetPseudoStyle(doc.GetElementById("r"), PseudoElementKind.SliderTrack));
    }
}
